  # The Enum type ProcessMessageResult.

  def write_TypeProcessMessageResult(v)
    if v.application_message?
      pack_into(4, 'l>', 1)
      self.write_TypeMessage(v.message)
    end
    if v.proposal?
      pack_into(4, 'l>', 2)
      self.write_TypeUpdateGroupResult(v.result)
    end
    if v.pending_proposal?
      pack_into(4, 'l>', 3)
      self.write_String(v.mls_group_id)
    end
    if v.external_join_proposal?
      pack_into(4, 'l>', 4)
      self.write_String(v.mls_group_id)
    end
    if v.commit?
      pack_into(4, 'l>', 5)
      self.write_String(v.mls_group_id)
    end
    if v.unprocessable?
      pack_into(4, 'l>', 6)
      self.write_String(v.mls_group_id)
    end
    if v.ignored_proposal?
      pack_into(4, 'l>', 7)
      self.write_String(v.mls_group_id)
      self.write_String(v.reason)
    end
    if v.previously_failed?
      pack_into(4, 'l>', 8)
    end
 end
   

